:root {
  --color-bg: #1e1e2f;
  --color-card: #2a2a40;
  --color-primary: #f9c74f;
  --color-accent: #90be6d;
  --color-text: #f0f0f5;
  --color-muted: #a0a0b8;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.app-card {
  background: var(--color-card);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-primary);
}

.subtitle {
  color: var(--color-muted);
  margin-top: 4px;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 12px;
  color: var(--color-primary);
}

.mood-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
}

.mood-btn {
  background: transparent;
  border: 2px solid var(--color-muted);
  border-radius: var(--radius);
  padding: 12px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  color: var(--color-text);
  font-size: 0.875rem;
  transition: border-color 0.2s, transform 0.1s, background 0.2s;
  min-width: 64px;
}

.mood-btn:hover {
  border-color: var(--color-primary);
  background: rgba(249, 199, 79, 0.1);
}

.mood-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.mood-btn:active {
  transform: scale(0.95);
}

.mood-btn[aria-checked="true"] {
  border-color: var(--color-primary);
  background: rgba(249, 199, 79, 0.15);
}

.face {
  width: 40px;
  height: 40px;
  position: relative;
  border-radius: 50%;
  background: var(--color-muted);
  display: inline-block;
}

.eye {
  width: 6px;
  height: 6px;
  background: var(--color-bg);
  border-radius: 50%;
  position: absolute;
  top: 12px;
}

.eye.left { left: 10px; }
.eye.right { right: 10px; }

.mouth {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  width: 16px;
  height: 8px;
  border: 2px solid var(--color-bg);
  border-top: none;
  border-radius: 0 0 16px 16px;
}

.mouth.frown {
  border: 2px solid var(--color-bg);
  border-bottom: none;
  border-radius: 16px 16px 0 0;
  bottom: 12px;
}

.mouth.angry {
  border: 2px solid var(--color-bg);
  border-bottom: none;
  border-radius: 16px 16px 0 0;
  bottom: 12px;
  width: 12px;
}

.mouth.anxious {
  border: 2px solid var(--color-bg);
  border-radius: 50%;
  width: 10px;
  height: 10px;
  bottom: 8px;
}

.mouth.calm {
  border: 2px solid var(--color-bg);
  border-radius: 0 0 4px 4px;
  width: 14px;
  height: 4px;
  bottom: 10px;
}

.note-section {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
  color: var(--color-muted);
}

textarea {
  width: 100%;
  padding: 12px;
  border-radius: var(--radius);
  border: 2px solid var(--color-muted);
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font);
  font-size: 1rem;
  resize: vertical;
}

textarea:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-color: var(--color-primary);
}

.primary-btn {
  width: 100%;
  padding: 14px;
  background: var(--color-primary);
  color: var(--color-bg);
  border: none;
  border-radius: var(--radius);
  font-size: 1.125rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  margin-bottom: 24px;
}

.primary-btn:hover {
  background: #f7b731;
}

.primary-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.primary-btn:active {
  transform: scale(0.98);
}

.counts-section,
.entries-section {
  margin-bottom: 24px;
}

.counts-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.counts-list li {
  background: var(--color-bg);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.875rem;
  color: var(--color-muted);
}

.entries-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.entry {
  background: var(--color-bg);
  padding: 12px 16px;
  border-radius: var(--radius);
  border-left: 4px solid var(--color-primary);
}

.entry-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.entry-mood {
  font-weight: 700;
  color: var(--color-accent);
  text-transform: capitalize;
}

.entry-date {
  font-size: 0.75rem;
  color: var(--color-muted);
}

.entry-note {
  font-size: 0.9375rem;
  color: var(--color-text);
  word-break: break-word;
}

.empty-message {
  color: var(--color-muted);
  font-style: italic;
  text-align: center;
  padding: 16px 0;
}

@media (max-width: 400px) {
  .app-card {
    padding: 24px 16px;
  }
  .mood-btn {
    flex: 1 1 30%;
  }
  h1 {
    font-size: 1.5rem;
  }
}

(() => {
  const MOODS = ['happy', 'sad', 'angry', 'anxious', 'calm'];
  const STORAGE_KEY = 'pixelMoodJournal';

  let entries = [];
  let selectedMood = null;

  const moodButtons = document.querySelectorAll('.mood-btn');
  const noteInput = document.getElementById('note-input');
  const addBtn = document.getElementById('add-entry');
  const entriesList = document.getElementById('entries-list');
  const countsList = document.getElementById('mood-counts');
  const emptyMsg = document.getElementById('empty-message');

  function loadEntries() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        entries = JSON.parse(stored);
      }
    } catch (e) {
      entries = [];
    }
  }

  function saveEntries() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(entries));
    } catch (e) {
      // fallback: in-memory only
    }
  }

  function todayStr() {
    const d = new Date();
    return d.toISOString().slice(0, 10);
  }

  function selectMood(mood) {
    selectedMood = mood;
    moodButtons.forEach(btn => {
      const isSelected = btn.dataset.mood === mood;
      btn.setAttribute('aria-checked', isSelected ? 'true' : 'false');
      btn.tabIndex = isSelected ? 0 : -1;
    });
  }

  function renderCounts() {
    const counts = {};
    MOODS.forEach(m => counts[m] = 0);
    entries.forEach(e => {
      if (counts[e.mood] !== undefined) counts[e.mood]++;
    });
    countsList.innerHTML = '';
    MOODS.forEach(m => {
      const li = document.createElement('li');
      li.textContent = `${m}: ${counts[m]}`;
      countsList.appendChild(li);
    });
  }

  function renderEntries() {
    entriesList.innerHTML = '';
    const sorted = [...entries].sort((a, b) => b.timestamp - a.timestamp);
    if (sorted.length === 0) {
      emptyMsg.style.display = 'block';
      return;
    }
    emptyMsg.style.display = 'none';
    sorted.forEach(entry => {
      const li = document.createElement('li');
      li.className = 'entry';
      const header = document.createElement('div');
      header.className = 'entry-header';
      const moodSpan = document.createElement('span');
      moodSpan.className = 'entry-mood';
      moodSpan.textContent = entry.mood;
      const dateSpan = document.createElement('span');
      dateSpan.className = 'entry-date';
      dateSpan.textContent = entry.date;
      header.appendChild(moodSpan);
      header.appendChild(dateSpan);
      li.appendChild(header);
      if (entry.note) {
        const noteP = document.createElement('p');
        noteP.className = 'entry-note';
        noteP.textContent = entry.note;
        li.appendChild(noteP);
      }
      entriesList.appendChild(li);
    });
  }

  function addEntry() {
    if (!selectedMood) {
      noteInput.focus();
      return;
    }
    const note = noteInput.value.trim();
    const entry = {
      mood: selectedMood,
      note: note,
      date: todayStr(),
      timestamp: Date.now()
    };
    entries.push(entry);
    saveEntries();
    noteInput.value = '';
    renderEntries();
    renderCounts();
  }

  // Keyboard navigation within mood radiogroup
  function handleMoodKeydown(e) {
    const currentIndex = MOODS.indexOf(selectedMood);
    let newIndex = currentIndex;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
      e.preventDefault();
      newIndex = (currentIndex + 1) % MOODS.length;
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
      e.preventDefault();
      newIndex = (currentIndex - 1 + MOODS.length) % MOODS.length;
    } else if (e.key === ' ' || e.key === 'Enter') {
      e.preventDefault();
      return;
    } else {
      return;
    }
    selectMood(MOODS[newIndex]);
    const targetBtn = document.querySelector(`.mood-btn[data-mood="${MOODS[newIndex]}"]`);
    if (targetBtn) targetBtn.focus();
  }

  // Event listeners
  moodButtons.forEach(btn => {
    btn.addEventListener('click', () => selectMood(btn.dataset.mood));
    btn.addEventListener('keydown', handleMoodKeydown);
  });

  addBtn.addEventListener('click', addEntry);

  // Init
  loadEntries();
  renderEntries();
  renderCounts();
})();
